style.css:
body {
    background-color: #3b3b3b; /* Темно-сірий колір для резервного фону */
    background-image: url('https://i.imgur.com/H4fXz1n.png'); /* URL зображення для фону */
    background-size: cover; /* Масштабування зображення, щоб покривати весь екран */
    background-repeat: no-repeat; /* Уникаємо повторів */
    background-position: center; /* Центруємо фон */
    margin: 0;
    padding: 0;
}
